const usageByHousehold = `-- name: UsageByHousehold :many
SELECT h.id AS household_id, h.name,
       count(u.id)::bigint AS calls,
       coalesce(sum(u.input_tokens), 0)::bigint AS input_tokens,
       coalesce(sum(u.output_tokens), 0)::bigint AS output_tokens
FROM households h
LEFT JOIN usage_log u ON u.household_id = h.id AND u.created_at >= $1
GROUP BY h.id, h.name
ORDER BY h.name
`

type UsageByHouseholdRow struct {
	HouseholdID  uuid.UUID
	Name         string
	Calls        int64
	InputTokens  int64
	OutputTokens int64
}

func (q *Queries) UsageByHousehold(ctx context.Context, since time.Time) ([]UsageByHouseholdRow, error) {
	rows, err := q.db.Query(ctx, usageByHousehold, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsageByHouseholdRow{}
	for rows.Next() {
		var i UsageByHouseholdRow
		if err := rows.Scan(
			&i.HouseholdID,
			&i.Name,
			&i.Calls,
			&i.InputTokens,
			&i.OutputTokens,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
